java.code:
int i = 0;
i++;                        // 后缀：表达式的值是加之前的 0
++i;                        // 前缀：表达式的值是加之后的 2

int[] arr = {1, 2};
int idx = 0;
arr[idx++];                 // ⚠ 取值并前进
arr[++idx];                 // ⚠ 先前进再取值 —— 与上一行只差一位

// 单独成句时 i++ 与 ++i 完全相同，只有嵌在表达式里才有区别

